class Solution {
public:
    double probabilityOfHeads(vector<double>& prob, int target) {
        vector<double> dp(target + 1, 0.0);
        dp[0] = 1.0;
        int used = 0;
        for (double p : prob) {
            ++used;
            for (int heads = min(target, used); heads >= 0; --heads) {
                double without = dp[heads] * (1.0 - p);
                double with = heads > 0 ? dp[heads - 1] * p : 0.0;
                dp[heads] = without + with;
            }
        }
        return dp[target];
    }
};
